// app/posts/route.ts
import { NextResponse } from "next/server";

async function getPosts() {
  const res = await fetch("https://api.example.com/posts", {
    next: { revalidate: 60 },
  });
  return res.json();
}

export async function GET() {
  const posts = await getPosts();
  return NextResponse.json({ posts });
}

